import{_ as e,r as a,o,c,e as n,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Вложения файлов - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Создание новых вложений","slug":"создание-новых-вложении","link":"#создание-новых-вложении","children":[{"level":3,"title":"Обработка множественных вложений","slug":"обработка-множественных-вложении","link":"#обработка-множественных-вложении","children":[]}]},{"level":2,"title":"Просмотр вложений","slug":"просмотр-вложении","link":"#просмотр-вложении","children":[{"level":3,"title":"Доступ к локальному пути","slug":"доступ-к-локальному-пути","link":"#доступ-к-локальному-пути","children":[]}]},{"level":2,"title":"Изменение размера миниатюр","slug":"изменение-размера-миниатюр","link":"#изменение-размера-миниатюр","children":[]},{"level":2,"title":"Вывод и скачивание","slug":"вывод-и-скачивание","link":"#вывод-и-скачивание","children":[]},{"level":2,"title":"Пример использования","slug":"пример-использования","link":"#пример-использования","children":[]},{"level":2,"title":"Пример валидации","slug":"пример-валидации","link":"#пример-валидации","children":[]}],"relativePath":"3.x/ru/extend/database/attachments.md","filePath":"3.x/ru/extend/database/attachments.md"}'),i={name:"3.x/ru/extend/database/attachments.md"};function r(k,s,d,g,m,h){const t=a("pre-heading"),p=a("post-heading");return o(),c("div",null,[n(t),s[0]||(s[0]=l("h1",null,"Вложения файлов",-1)),n(p),s[1]||(s[1]=u(`<p>Модели могут поддерживать вложения файлов, используя подмножество <a href="./relations.html">полиморфных связей</a>. Связи <code>$attachOne</code> или <code>$attachMany</code> предназначены для привязки файла к записи базы данных, называемой «вложениями». Практически во всех случаях модель <code>System\\Models\\File</code> используется для поддержания этой связи, где ссылки на файлы хранятся как записи в таблице <code>system_files</code> и имеют полиморфную связь с родительской моделью.</p><p>В примерах ниже модель имеет одну модель вложения Avatar и много моделей вложений Photo.</p><p>Одно вложение файла:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;avatar&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Несколько вложений файлов:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>Во избежание конфликта имён убедитесь, что таблица базы данных вашей модели не имеет атрибута с тем же именем, что и ваша связь вложения.</p></div><p>Защищённые вложения загружаются в директорию <strong>uploads/protected</strong> приложения, которая недоступна для прямого доступа из Web. Защищённое вложение файла определяется путём установки свойства <code>public</code> в <code>false</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;avatar&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;public&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="создание-новых-вложении"><a href="#создание-новых-вложении" class="header-anchor">#</a> Создание новых вложений</h2><p>Для связей единичного вложения (<code>$attachOne</code>) вы можете создать вложение напрямую через связь модели, установив его значение с помощью функции <code>files</code>, которая читает данные файла из загрузки input.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для ассоциации нового файла из локального пути используйте модель <code>System\\Models\\File</code> и метод <code>fromFile</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/path/to/somefile.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для создания файла напрямую из (необработанных) данных используйте метод <code>fromData</code>, чтобы передать содержимое (первый аргумент) и имя файла (второй аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromData</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Some content&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;sometext.txt&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете добавить файл из URL с помощью метода <code>fromUrl</code>. Для использования этого метода необходимо установить расширение cURL PHP.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://example.tld/path/to/avatar.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Опционально вы можете указать пользовательское имя файла (второй аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">File</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromUrl</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;https://example.tld/avatar.jpg&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;customname.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="обработка-множественных-вложении"><a href="#обработка-множественных-вложении" class="header-anchor">#</a> Обработка множественных вложений</h3><p>Для связей множественных вложений (<code>$attachMany</code>) вы можете передать массив значений из функции <code>files()</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">photos</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;multi_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете использовать метод <code>create</code> для добавления файла к существующей связи, обратите внимание, что объект файла ассоциируется с атрибутом <code>data</code>. Этот подход также может использоваться для единичных связей, если вы предпочитаете.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете использовать метод <code>add</code> для связи, чтобы работать напрямую с моделью <code>System\\Models\\File</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">fromFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/path/to/somefile.jpg&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Альтернативно вы можете подготовить модель File заранее, а затем вручную ассоциировать связь позже. Обратите внимание, что атрибут <code>is_public</code> должен быть установлен явно при этом подходе.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$file</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">data</span> <span class="token operator">=</span> <span class="token function">files</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file_input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">is_public</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">photos</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token variable">$file</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="просмотр-вложении"><a href="#просмотр-вложении" class="header-anchor">#</a> Просмотр вложений</h2><p>Метод <code>getUrl</code> возвращает полный URL загруженного публичного файла. Следующий код выведет что-то вроде <strong>example.tld/uploads/public/path/to/avatar.jpg</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Возврат путей множественных вложений.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">photos</span> <span class="token keyword">as</span> <span class="token variable">$photo</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$photo</span><span class="token operator">-&gt;</span><span class="token function">getUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Отображение файла на странице с помощью Twig.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> model<span class="token punctuation">.</span>avatar<span class="token punctuation">.</span>url <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Description Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><h3 id="доступ-к-локальному-пути"><a href="#доступ-к-локальному-пути" class="header-anchor">#</a> Доступ к локальному пути</h3><p>Метод <code>getLocalPath</code> вернёт абсолютный путь загруженного файла в локальной файловой системе. При использовании внешнего драйвера, такого как S3, этот метод скачает содержимое во временное расположение в локальной файловой системе.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getLocalPath</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="изменение-размера-миниатюр"><a href="#изменение-размера-миниатюр" class="header-anchor">#</a> Изменение размера миниатюр</h2><p>Вы можете изменить размер изображения с помощью метода <code>getThumbUrl</code>. Метод принимает 3 параметра — ширину изображения, высоту изображения и параметр опций.</p><p>Параметры <strong>width</strong> и <strong>height</strong> должны быть указаны как число или как слово <strong>auto</strong> для автоматического пропорционального масштабирования.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">echo</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">getThumbUrl</span><span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Отображение изображения на странице с помощью Twig.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> model<span class="token punctuation">.</span>avatar<span class="token punctuation">.</span>thumbUrl<span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> mode<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>exact<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> quality<span class="token punctuation">:</span> <span class="token number">80</span><span class="token punctuation">,</span> extension<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>webp<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Description Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>Подробнее о доступных параметрах <code>getThumbUrl</code> читайте в <a href="./../services/resizer.html">статье об изменении размера изображений</a>.</p><h2 id="вывод-и-скачивание"><a href="#вывод-и-скачивание" class="header-anchor">#</a> Вывод и скачивание</h2><p>Для прямого вывода содержимого файла используйте метод <code>output</code>, который возвращает <a href="./../services/response-view.html">объект ответа</a>, включающий необходимые заголовки для отображения файла в браузере.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">output</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы можете вывести содержимое в браузер, вызвав метод <code>send</code> по цепочке.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">output</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Верните метод <code>download</code> для скачивания файла в качестве ответа.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">avatar</span><span class="token operator">-&gt;</span><span class="token function">download</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="пример-использования"><a href="#пример-использования" class="header-anchor">#</a> Пример использования</h2><p>Этот раздел показывает полный пример использования функции вложений модели — от определения связи в модели до отображения загруженного изображения на странице.</p><p>Внутри вашей модели определите связь с классом <code>System\\Models\\File</code>, например:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$attachOne</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;featured_image&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Создайте форму для загрузки файла:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;files&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>example_file<span class="token punctuation">&quot;</span></span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>file<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Upload File<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>Обработайте загруженный файл на сервере и прикрепите его к модели:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Find the Blog Post model</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Save the featured image of the Blog Post model</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">hasFile</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Альтернативно вы можете использовать <a href="./relations.html">отложенную привязку</a> для отсрочки связи.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Find the Blog Post model</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Look for the postback data &#39;example_file&#39; in the HTML form above</span>
<span class="token variable">$fileFromPost</span> <span class="token operator">=</span> <span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;example_file&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// If it exists, save it as the featured image with a deferred session key</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$fileFromPost</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token function">featured_image</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$fileFromPost</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Отобразите загруженный файл на странице:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>
<span class="token comment">// Find the Blog Post model again</span>
<span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Look for the featured image address, otherwise use a default one</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$featuredImage</span> <span class="token operator">=</span> <span class="token variable">$post</span><span class="token operator">-&gt;</span><span class="token property">featured_image</span><span class="token operator">-&gt;</span><span class="token function">getUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">else</span> <span class="token punctuation">{</span>
    <span class="token variable">$featuredImage</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;http://placehold.it/220x300&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$featuredImage</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">alt</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Featured Image<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>Если вам нужно получить доступ к владельцу файла, вы можете использовать свойство <code>attachment</code> модели <code>File</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$morphTo</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;attachment&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Пример:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$user</span> <span class="token operator">=</span> <span class="token variable">$file</span><span class="token operator">-&gt;</span><span class="token property">attachment</span><span class="token punctuation">;</span>
</code></pre></div><p>Для получения дополнительной информации читайте о <a href="./relations.html#relation-polymorphic-relations">полиморфных связях</a></p><h2 id="пример-валидации"><a href="#пример-валидации" class="header-anchor">#</a> Пример валидации</h2><p>Пример ниже использует <a href="./../services/validation.html">валидацию массива</a> для валидации связей <code>$attachMany</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">use</span> <span class="token package">System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>File</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Gallery</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">use</span> <span class="token package"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Rain<span class="token punctuation">\\</span>Database<span class="token punctuation">\\</span>Traits<span class="token punctuation">\\</span>Validation</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$attachMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">File</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;photos&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;required&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;photos.*&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;image&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;max:1000&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;dimensions:min_width=100,min_height=100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Для получения дополнительной информации о синтаксисе <code>attribute.*</code>, используемом выше, смотрите <a href="./../services/validation.html">статью о валидации</a> по валидации массивов.</p>`,74))])}const b=e(i,[["render",r]]);export{f as __pageData,b as default};
